import React from 'react'
import Card from 'react-bootstrap/Card';

const Success = ({ name, type }) => {
  return (
    <div>
    <Card className="text-center mt-5">
      <h1>Success!</h1>
      <p>Welcome, {name}! You have been {type} successfully.</p>
      </Card>
    </div>
  )
}

export default Success
